import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.D9E58p8B.js";const m=JSON.parse('{"title":"Agir","description":"","frontmatter":{"title":"Agir"},"headers":[],"relativePath":"agent/agir.md","filePath":"agent/agir.md"}'),d={name:"agent/agir.md"};function r(i,e,s,u,c,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="agir" tabindex="-1">Agir <a class="header-anchor" href="#agir" aria-label="Permalink to &quot;Agir&quot;">​</a></h1><p>Les Mains permettent à l&#39;agent de cliquer, saisir du texte, appuyer sur un bouton, glisser et piloter les fenêtres. C&#39;est ce que <strong>vous</strong> bornez, avec le plafond.</p><h2 id="ce-que-vous-demandez" tabindex="-1">Ce que vous demandez <a class="header-anchor" href="#ce-que-vous-demandez" aria-label="Permalink to &quot;Ce que vous demandez&quot;">​</a></h2><blockquote><p>« Ouvre le menu Fichier. »</p><p>« Remplis le champ Nom avec &quot;Dupont&quot;, puis valide. »</p></blockquote><h2 id="avant-d-agir-le-plafond" tabindex="-1">Avant d&#39;agir : le plafond <a class="header-anchor" href="#avant-d-agir-le-plafond" aria-label="Permalink to &quot;Avant d&#39;agir : le plafond&quot;">​</a></h2><p>Le plafond est réglé à <strong>L0</strong> par défaut : l&#39;agent ne peut qu&#39;observer. Pour qu&#39;il agisse, montez le curseur du panneau (L1 à L3) : voir <a href="/Daimon/guide/plafond-et-exclusions.html">Plafond et exclusions</a>.</p><p>Un agent bien conduit appelle d&#39;abord <a href="/Daimon/reference/diagnostic.html#main-ceiling"><code>main_ceiling</code></a>. L&#39;outil rend le plafond actif, et <code>gated_above</code> liste les outils refusés à ce niveau : l&#39;agent annonce d&#39;emblée ce qu&#39;il ne pourra pas faire, au lieu d&#39;être refusé en cours de route. <strong>Il ne peut pas relever le plafond</strong> : c&#39;est à vous de le faire.</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Ce qu&#39;il permet</th><th>Outils</th></tr></thead><tbody><tr><td>L1</td><td>Actions réversibles : focus, fenêtres, navigation</td><td><code>main_navigate</code>, <code>main_hover</code>, <code>main_activate</code>, <code>main_window_*</code></td></tr><tr><td>L2</td><td>Clics, saisie, glisser, touches</td><td><code>main_click</code>, <code>main_type</code>, <code>main_drag</code>, <code>main_key</code></td></tr><tr><td>L3</td><td>Les boutons qui engagent</td><td><code>main_press</code></td></tr><tr><td>L4</td><td>Tout, sans confirmation action par action</td><td><code>main_mouse_*</code>, <code>main_key_down</code>, <code>main_key_up</code></td></tr></tbody></table><h2 id="ce-que-fait-l-agent" tabindex="-1">Ce que fait l&#39;agent <a class="header-anchor" href="#ce-que-fait-l-agent" aria-label="Permalink to &quot;Ce que fait l&#39;agent&quot;">​</a></h2><ol><li>Il <strong>regarde</strong> : <a href="/Daimon/agent/regarder.html">Regarder l&#39;écran</a> ou <a href="/Daimon/agent/lire-interface.html">Lire une interface</a>, pour obtenir une position fiable.</li><li>Il <strong>agit</strong>, en déclarant son <code>intent</code> : une phrase qui dit ce qu&#39;il veut faire, consignée au journal d&#39;audit. Les outils qui s&#39;engagent portent aussi <code>reversible</code>, que l&#39;agent doit renseigner honnêtement.</li><li>Il <strong>vérifie</strong> : un nouveau regard confirme le résultat.</li></ol><p>Pour cliquer, l&#39;agent passe de préférence <code>role</code> et <code>label</code> (relevés avec <code>touche_probe</code>) : Daimon peut ainsi vérifier la réversibilité de la cible. Pour saisir, il clique d&#39;abord dans le champ, car <code>main_type</code> ne choisit pas la cible. Le texte saisi n&#39;est <strong>jamais</strong> écrit dans le journal d&#39;audit.</p><p>Pour viser, l&#39;agent donne soit des points globaux (ceux que renvoie <code>vue_find</code>), soit, avec <code>space=&quot;image&quot;</code> et un <code>display</code>, des pixels d&#39;une capture que Daimon convertit lui-même.</p><h2 id="ce-que-vous-obtenez" tabindex="-1">Ce que vous obtenez <a class="header-anchor" href="#ce-que-vous-obtenez" aria-label="Permalink to &quot;Ce que vous obtenez&quot;">​</a></h2><p>Chaque outil d&#39;action répond sous l&#39;une de ces trois formes :</p><table tabindex="0"><thead><tr><th>Réponse</th><th>Sens</th></tr></thead><tbody><tr><td><code>{&quot;status&quot;: &quot;done&quot;, …}</code></td><td>L&#39;action a été exécutée</td></tr><tr><td><code>{&quot;status&quot;: &quot;refused&quot;, &quot;reason&quot;: &quot;…&quot;}</code></td><td>L&#39;action est refusée : plafond, garde, confirmation humaine non obtenue</td></tr><tr><td><code>{&quot;status&quot;: &quot;error&quot;, &quot;reason&quot;: &quot;…&quot;}</code></td><td>L&#39;action n&#39;a pas pu s&#39;exécuter</td></tr></tbody></table><h2 id="les-confirmations" tabindex="-1">Les confirmations <a class="header-anchor" href="#les-confirmations" aria-label="Permalink to &quot;Les confirmations&quot;">​</a></h2><p>Jusqu&#39;à L3, une action que Daimon juge <strong>irréversible</strong>, ou que l&#39;agent déclare telle, s&#39;arrête sur une boîte de confirmation. Vous répondez ; sans réponse, elle refuse d&#39;elle-même au bout de 30 secondes, et l&#39;agent reçoit <code>refused</code>.</p><p>À <strong>L4</strong>, il n&#39;y a plus de confirmation action par action. Ce niveau demande votre consentement explicite, depuis le panneau ou le terminal ; aucun outil ne permet à l&#39;agent de l&#39;engager.</p><h2 id="si-l-appel-est-refuse-ou-echoue" tabindex="-1">Si l&#39;appel est refusé ou échoue <a class="header-anchor" href="#si-l-appel-est-refuse-ou-echoue" aria-label="Permalink to &quot;Si l&#39;appel est refusé ou échoue&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cas</th><th>Ce que l&#39;agent doit faire</th></tr></thead><tbody><tr><td><code>refused</code> au-dessus du plafond</td><td>Dire que l&#39;action dépasse le plafond, et demander à la personne de le relever si elle le souhaite</td></tr><tr><td><code>refused</code>, confirmation non obtenue</td><td>Ne pas insister : la personne a refusé ou n&#39;a pas répondu</td></tr><tr><td><code>done</code> sans aucun effet</td><td>Sans l&#39;autorisation <strong>Accessibilité</strong>, <code>main_type</code>, <code>main_key</code>, <code>main_hover</code> et <code>main_navigate</code> répondent <code>done</code> <strong>sans rien faire</strong> : appeler <code>daimon_doctor</code></td></tr><tr><td>Attente de 30 secondes</td><td>Sans Accessibilité, <code>main_click</code>, <code>main_press</code> et <code>main_drag</code> attendent une confirmation : appeler <code>daimon_doctor</code></td></tr><tr><td><code>invalid_arguments</code></td><td>Par exemple <code>space=&quot;image&quot;</code> sans <code>display</code> : corriger l&#39;argument</td></tr><tr><td><code>motor_unavailable</code></td><td>Les Mains ne sont pas disponibles sur cet hôte</td></tr></tbody></table><p>Détail complet : <a href="/Daimon/reference/mains.html">Mains</a>.</p><p>Suite : <a href="/Daimon/agent/montrer.html">Montrer ce qui se passe</a>.</p>',22)])])}const g=t(d,[["render",r]]);export{m as __pageData,g as default};
